<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('admin',['assessment_manager']);csrf_check();$a=$_POST['_action']??'';
if($a==='cat'){db()->prepare("INSERT INTO evaluation_categories(name,description) VALUES(?,?)")->execute([trim($_POST['name']),trim($_POST['desc'])]);flash('Category added');redirect('evaluations.php');}
if($a==='score'){$sc=(float)$_POST['score'];if($sc<0||$sc>100){flash('Score must be 0-100','danger');redirect('evaluations.php');}
 db()->prepare("INSERT INTO employee_assessments(employee_id,category_id,batch_title,eval_date,score_percent,tasks_count,remarks,is_published) VALUES(?,?,?,?,?,?,?,?)")->execute([(int)$_POST['emp'],(int)$_POST['cat'],trim($_POST['batch']),$_POST['date'],$sc,(int)$_POST['tasks'],trim($_POST['remarks']),isset($_POST['pub'])?1:0]);audit($u['id'],'Added score for emp #'.(int)$_POST['emp']);flash('Score saved');redirect('evaluations.php');}
if($a==='pub'){db()->prepare("UPDATE employee_assessments SET is_published=1-is_published WHERE id=?")->execute([(int)$_POST['id']]);audit($u['id'],'Toggled publish #'.(int)$_POST['id']);redirect('evaluations.php');}
if($a==='del'){db()->prepare("DELETE FROM employee_assessments WHERE id=?")->execute([(int)$_POST['id']]);audit($u['id'],'Deleted assessment #'.(int)$_POST['id']);redirect('evaluations.php');}
$emps=db()->query("SELECT id,employee_code,full_name FROM employees WHERE status<>'Inactive' ORDER BY employee_code")->fetchAll();$cats=db()->query("SELECT id,name FROM evaluation_categories WHERE is_active=1")->fetchAll();
$rows=db()->query("SELECT a.*,e.employee_code,c.name cat FROM employee_assessments a JOIN employees e ON e.id=a.employee_id JOIN evaluation_categories c ON c.id=a.category_id ORDER BY a.id DESC LIMIT 100")->fetchAll();page_head('Evaluations',[],$u);?>
<form method="post" class="card p-3 mb-3 row g-2 flex-row"><?=csrf_field()?><input type="hidden" name="_action" value="score">
<div class="col-md-3"><select class="form-select" name="emp" required><?php foreach($emps as $x)echo'<option value="'.$x['id'].'">'.e($x['employee_code'].' – '.$x['full_name']).'</option>';?></select></div>
<div class="col-md-3"><select class="form-select" name="cat"><?php foreach($cats as $x)echo'<option value="'.$x['id'].'">'.e($x['name']).'</option>';?></select></div>
<div class="col-md-3"><input class="form-control" name="batch" placeholder="Batch / assessment title" required></div><div class="col-md-3"><input class="form-control" type="date" name="date" required></div>
<div class="col-md-2"><input class="form-control" type="number" step="0.01" min="0" max="100" name="score" placeholder="Score %" required></div><div class="col-md-2"><input class="form-control" type="number" name="tasks" placeholder="Tasks"></div>
<div class="col-md-4"><input class="form-control" name="remarks" placeholder="Remarks"></div><div class="col-md-2"><label class="form-check"><input type="checkbox" class="form-check-input" name="pub" checked> Publish</label></div><div class="col-md-2"><button class="btn btn-primary w-100">Save</button></div></form>
<form method="post" class="card p-3 mb-4 row g-2 flex-row"><?=csrf_field()?><input type="hidden" name="_action" value="cat"><div class="col-md-4"><input class="form-control" name="name" placeholder="New category name" required></div><div class="col-md-6"><input class="form-control" name="desc" placeholder="Description"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Add category</button></div></form>
<div class="card table-responsive"><table class="table mb-0"><tr><th>Emp</th><th>Category</th><th>Batch</th><th>Date</th><th>Score</th><th>Rating</th><th>State</th><th></th></tr><?php foreach($rows as $r){$rt=rating_for($r['score_percent']);?><tr><td><?=e($r['employee_code'])?></td><td><?=e($r['cat'])?></td><td><?=e($r['batch_title'])?></td><td><?=e($r['eval_date'])?></td><td><?=e($r['score_percent'])?>%</td><td><span class="badge text-bg-<?=e($rt['color'])?>"><?=e($rt['label'])?></span></td><td><?=$r['is_published']?'Published':'Hidden'?></td>
<td class="d-flex gap-1"><?php foreach(['pub'=>'Publish/Hide','del'=>'Delete'] as $k=>$l){?><form method="post" <?=$k==='del'?'onsubmit="return confirm(\'Delete?\')"':''?>><?=csrf_field()?><input type="hidden" name="_action" value="<?=$k?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary"><?=$l?></button></form><?php }?></td></tr><?php }?></table></div><?php page_foot();
